import random

def raises(exception_type, function, *args):
    try:
        function(*args)
    except exception_type:
        return True
    except Exception as error:
        raise AssertionError(f"expected {exception_type.__name__}, got {type(error).__name__}: {error}")
    raise AssertionError(f"expected {exception_type.__name__}, but nothing was raised")

def join(x, y):
    """A fresh counter holding the merge of x and y; neither of them is changed."""
    result = GCounter("scratch", x.snapshot())
    result.merge(y)
    return result

def exchange(schedule):
    """Three replicas count 2, 3 and 5, then merge as scheduled: (destination, source) pairs. Returns every replica's snapshot."""
    replicas = {name: GCounter(name) for name in "abc"}
    replicas["a"].increment(2)
    replicas["b"].increment(3)
    replicas["c"].increment(5)
    for destination, source in schedule:
        replicas[destination].merge(replicas[source])
    return {name: replica.snapshot() for name, replica in replicas.items()}

