def broken_law(trials):
    for _ in range(trials):
        x, y, z = random_counter(), random_counter(), random_counter()
        if join(x, y).snapshot() != join(y, x).snapshot():
            return f"not commutative for {x.snapshot()} and {y.snapshot()}"
        if join(join(x, y), z).snapshot() != join(x, join(y, z)).snapshot():
            return f"not associative for {x.snapshot()}, {y.snapshot()} and {z.snapshot()}"
        if join(x, x).snapshot() != x.snapshot():
            return f"not idempotent for {x.snapshot()}"
    return "none"

assert broken_law(200) == "none"

