class GCounter:
    def __init__(self, replica_id, snapshot=None):
        self._replica_id = replica_id
        self._counts = dict(snapshot or {})       # replica id -> how many increments that replica has made

    def increment(self, amount=1):
        if amount <= 0:
            raise ValueError(f"a grow-only counter can only grow; got {amount}")
        self._counts[self._replica_id] = self._counts.get(self._replica_id, 0) + amount

    def value(self):
        return sum(self._counts.values())

    def merge(self, other):
        # Per replica keep the larger count. max() is commutative, associative and idempotent,
        # and so therefore is the merge.
        for replica, count in other._counts.items():
            if count > self._counts.get(replica, 0):
                self._counts[replica] = count

    def snapshot(self):
        return dict(self._counts)
